(* [comment removed for export] *)
Definition PRM (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) (w h d : Z) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (RLF m s ret regs)
